47	/**
48	 * Global Exception handler for REST controllers.
49	 * <p>
50	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
51	 *
52	 * @author Vitaliy Fedoriv
53	 * @author Alexander Dudkin
54	 */
55	@ControllerAdvice
56	public class ExceptionControllerAdvice {
57	
58	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
59	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
60	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
61	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
62	
63	    /**
64	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
65	     * class.
66	     *
67	     * @param e     Object referring to the thrown exception.
68	     * @param status HTTP response status.
69	     * @param url URL request.
70	     */
71	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
72	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
73	        problemDetail.setType(URI.create(url.toString()));
74	        problemDetail.setTitle(e.getClass().getSimpleName());
75	        problemDetail.setDetail(detail);
76	        problemDetail.setProperty("timestamp", Instant.now());
77	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
78	        return problemDetail;
79	    }
80	
81	    /**
82	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
83	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
84	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
85	     * would catch it and report an authorization failure as a 500.
86	     *
87	     * @param e The {@link AccessDeniedException} to propagate
88	     * @throws AccessDeniedException always
89	     */
90	    @ExceptionHandler(AccessDeniedException.class)
91	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
92	        throw e;
93	    }
94	
95	    /**
96	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
97	     *
98	     * @param e The {@link Exception} to be handled
99	     * @param request {@link HttpServletRequest} object referring to the current request.
100	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
101	     */
102	    @ExceptionHandler(Exception.class)
103	    @ResponseBody
104	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
105	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
106	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
107	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
108	        return ResponseEntity.status(status).body(detail);
109	    }
110	
111	    /**
112	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
113	     * method returns a 404 Not Found status if an entity does not exist.
114	     *
115	     * @param e The {@link DataIntegrityViolationException} to be handled
116	     * @param request {@link HttpServletRequest} object referring to the current request.
117	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
118	     */
119	    @ExceptionHandler(DataIntegrityViolationException.class)
120	    @ResponseBody
121	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
122	        logger.warn("Data integrity violation at {} {}: {}",
123	            request.getMethod(),
124	            request.getRequestURI(),
125	            e.getMessage());
126	        logger.debug("Data integrity violation stacktrace", e);
127	        HttpStatus status = HttpStatus.NOT_FOUND;
128	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
129	        return ResponseEntity.status(status).body(detail);
130	    }
131	
132	    /**
133	     * Handles {@link DuplicateIdentityException}, raised when an owner is created or updated with a
134	     * whole identity key (normalized telephone, email and householdId) already used by another
135	     * owner. Returns a 409 Conflict status.
136	     *
137	     * @param e The {@link DuplicateIdentityException} to be handled
138	     * @param request {@link HttpServletRequest} object referring to the current request.
139	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
140	     */
141	    @ExceptionHandler(DuplicateIdentityException.class)
142	    @ResponseBody
143	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
144	        logger.warn("Duplicate identity at {} {}: {}",
145	            request.getMethod(),
146	            request.getRequestURI(),
147	            e.getMessage());
148	        HttpStatus status = HttpStatus.CONFLICT;
149	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
150	        return ResponseEntity.status(status).body(detail);
151	    }
152	
153	    /**
154	     * Handles {@link CityOwnerLimitException}, raised when an owner is created in a city that
155	     * already contains the maximum number of owners. Returns a 409 Conflict status.
156	     *
157	     * @param e The {@link CityOwnerLimitException} to be handled
158	     * @param request {@link HttpServletRequest} object referring to the current request.
159	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
160	     */
161	    @ExceptionHandler(CityOwnerLimitException.class)
162	    @ResponseBody
163	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitException(CityOwnerLimitException e, HttpServletRequest request) {
164	        logger.warn("City owner limit reached at {} {}: {}",
165	            request.getMethod(),
166	            request.getRequestURI(),
167	            e.getMessage());
168	        HttpStatus status = HttpStatus.CONFLICT;
169	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
170	        return ResponseEntity.status(status).body(detail);
171	    }
172	
173	    /**
174	     * Handles {@link DailyOwnerLimitException}, raised when an owner is created on a day that already
175	     * has the maximum number of owners registered. Returns a 429 Too Many Requests status.
176	     *
177	     * @param e The {@link DailyOwnerLimitException} to be handled
178	     * @param request {@link HttpServletRequest} object referring to the current request.
179	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
180	     */
181	    @ExceptionHandler(DailyOwnerLimitException.class)
182	    @ResponseBody
183	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
184	        logger.warn("Daily owner limit reached at {} {}: {}",
185	            request.getMethod(),
186	            request.getRequestURI(),
187	            e.getMessage());
188	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
189	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link InvalidPostcodeException}, raised when an owner is supplied with a postcode
195	     * that is out of range for its city's region. Returns a 400 Bad Request status.
196	     *
197	     * @param e The {@link InvalidPostcodeException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
200	     */
201	    @ExceptionHandler(InvalidPostcodeException.class)
202	    @ResponseBody
203	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
204	        logger.warn("Invalid postcode at {} {}: {}",
205	            request.getMethod(),
206	            request.getRequestURI(),
207	            e.getMessage());
208	        HttpStatus status = HttpStatus.BAD_REQUEST;
209	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
210	        return ResponseEntity.status(status).body(detail);
211	    }
