219	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
220	     */
221	    @ExceptionHandler(FutureRegistrationDateException.class)
222	    @ResponseBody
223	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
224	        logger.warn("Future registration date at {} {}: {}",
225	            request.getMethod(),
226	            request.getRequestURI(),
227	            e.getMessage());
228	        HttpStatus status = HttpStatus.BAD_REQUEST;
229	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
230	        return ResponseEntity.status(status).body(detail);
231	    }
232	
233	    /**
234	     * Handles {@link DisposableEmailDomainException}, raised when an owner is supplied with an email
235	     * whose domain is on the disposable-domain blocklist. Returns a 400 Bad Request status.
236	     *
237	     * @param e The {@link DisposableEmailDomainException} to be handled
238	     * @param request {@link HttpServletRequest} object referring to the current request.
239	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
240	     */
241	    @ExceptionHandler(DisposableEmailDomainException.class)
242	    @ResponseBody
243	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
244	        logger.warn("Disposable email domain at {} {}: {}",
245	            request.getMethod(),
246	            request.getRequestURI(),
247	            e.getMessage());
248	        HttpStatus status = HttpStatus.BAD_REQUEST;
249	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
250	        return ResponseEntity.status(status).body(detail);
251	    }
252	
253	    /**
254	     * Handles exception thrown by Bean Validation on controller methods parameters
255	     *
256	     * @param e The {@link MethodArgumentNotValidException} to be handled
257	     * @param request {@link HttpServletRequest} object referring to the current request.
258	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
259	     */
260	    @ExceptionHandler(MethodArgumentNotValidException.class)
261	    @ResponseBody
262	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
263	        HttpStatus status = HttpStatus.BAD_REQUEST;
264	        BindingErrorsResponse errors = new BindingErrorsResponse();
265	        BindingResult bindingResult = e.getBindingResult();
266	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
267	        if (bindingResult.hasErrors()) {
268	            errors.addAllErrors(bindingResult);
269	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
270	                .map(fieldError -> {
271	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
272	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
273	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
274	                        fieldError.getField(),
275	                        defaultMessage,
276	                        rejectedValue);
277	                    return new ValidationMessageDto(message)
278	                        .putAdditionalProperty("field", fieldError.getField())
279	                        .putAdditionalProperty("rejectedValue", rejectedValue)
280	                        .putAdditionalProperty("defaultMessage", defaultMessage);
281	                })
282	                .toList();
283	            logger.debug("Validation error at {} {}: {}",
284	                request.getMethod(),
285	                request.getRequestURI(),
286	                bindingResult.getFieldErrors());
287	            List<String> errorFields = bindingResult.getFieldErrors().stream()
288	                .map(FieldError::getField)
289	                .distinct()
290	                .toList();
291	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
292	            detail.setProperty("errors", errorFields);
293	            return ResponseEntity.status(status).body(detail);
294	        }
295	        return ResponseEntity.status(status).body(detail);
296	    }
297	
298	}
